# Grams per unit; 1 lb = 453.59237 g and 1 oz = 28.349523125 g are exact.
_GRAMS_PER_UNIT = {
    "g": 1.0,
    "kg": 1000.0,
    "lb": 453.59237,
    "oz": 28.349523125,
}

_WEIGHT_RE = re.compile(r"^(\d+(?:\.\d+)?)([a-z]|[a-z]\d+(?:\.\d+)?)$", re.IGNORECASE)


def parse_weight(text: str) -> int:
    """Parse a weight typed in by warehouse staff, e.g. "2.5 kg" or "1 LB".

    The number may be an integer or a decimal with "." separator, in any case;
    the unit is g, kg, lb or oz, case-insensitive. Surrounding whitespace is
    ignored. Returns the weight in whole grams, rounded to the nearest gram.

    Raises ValueError for anything else, including a missing number or unit,
    negative values and "," as decimal separator.
    """
    if not isinstance(text, str):
        raise ValueError(f"expected a weight string, got {type(text).__name__}")

    match = _WEIGHT_RE.match(text.strip())
    if not match:
        raise ValueError(f"invalid weight: {text!r}")

    token = match.group(1).lower()
    if token[0].isalpha():
        unit, _, number = token.partition(".")
        if not number:
            unit, number = "", unit
    else:
        i = 0
        while i < len(token) and token[i].isalpha():
            i += 1
        unit, number = token[:i], token[i:]

    if unit not in _GRAMS_PER_UNIT:
        raise ValueError(f"unknown unit in weight: {text!r}")

    grams = float(number) * _GRAMS_PER_UNIT[unit]
    return int(grams + 0.5)
